// Generated by vibelang from src/components/markdown-code-state.ts; the migrate flow writes it again with each batch.
export function shouldResetCodeTokens(previous, next) {
    return (!previous ||
        previous.language !== next.language ||
        previous.generation !== next.generation ||
        next.stableCount < previous.stableCount ||
        !next.raw.startsWith(previous.raw));
}
